INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66149001', 66149001, 'analyze_legacy', 'Kab. Garut', 'kabkota', 'Dinas Lingkungan Hidup', 'Penyusunan Dokumen Informasi Kinerja Pengelolaan Lingkungan Hidup (DIKPLHD/ SLHD)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Garut (Kab.)', 100000000, 'March 2026', 'APBD', 1, 1, '1 Dokumen', 'Penyusunan Dokumen Informasi Kinerja Pengelolaan Lingkungan Hidup (DIKPLHD/ SLHD);', 'a. Ruang lingkup pekerjaan/pengadaan jasa konsultansi: 1) Pembuatan SK Tim DSLHD 2026; 2) Menghimpun tabel data sesuai surat Sekretariat Jenderal KLHK perihal Penyampaian Pedoman DSLHD; 3) informasi kinerja pengelolaan lingkungan hidup tahun 2025 minimal data series 2 (dua) tahun terakhir yang meliputi: a) Matra SLHD diantaranya keanekaragaman hayati, kualitas air, laut, pesisir dan pantai, Kualitas udara, Lahan dan Hutan, Pengelolaan Sampah dan Limbah, Perubahan Iklim, Risiko Bencana; b) Kondisi Lingkungan Hidup dan Kecenderungannya (7 media), meliputi: air, udara, lahan, kehutanan, laut, kebencanaan, sampah. c) Sumber tekanan pencemaran (8 sektor), terdiri dari : industri, penduduk, pertambangan, pertanian/peternakan, rumah sakit & hotel, limbah B3, transportasi, energi. d) Upaya pengelolaan lingkungan (5 kegiatan), meliputi: penghijauan, rehabilitasi, perizinan lingkungan, penegakan hukum, produk hukum 4) Penyepakatan isu-isu penting lingkungan hidup; 5) Mengolah data informasi kinerja pengelolaan lingkungan hidup tahun 2024 sesuai dengan juknis penyusunan data yang diterbitkan oleh Kementerian Lingkungan Hidup dan Kehutanan. 6) Penyusunan Buku SLHD (Buku I dan II) dengan model analisis D-P-S-1-R (Driving Force-Pressure-State­lmpact-Response).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2590063);
