INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66192142', 66192142, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Obat Buffer Gizi Tahap II Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 392681322, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PT', 'Belanja Barang Persediaan Barang Konsumsi dengan Menyediakan Obat Buffer Gizi berupa Retinol (Vitamin A) 100.000 IU, Retinol (Vitamin A) 200.000 IU, Tablet Tambah Darah, Ready to Use Therapeutic Food (RUTF)', 'Spesifikasi Obat Buffer Gizi sebagai berikut : 1. Spesifikasi Teknis Tablet Tambah Darah (TTD) sesuai Permenkes Nomor 88 Tahun 2014 tentang Standar TTD bagi WUS dan Ibu Hamil a. Deskripsi Tablet Tambah Darah bagi Wanita Usia Subur dan Ibu Hamil: TTD berbentuk bulat/lonjong warna merah tua b. Komposisi Setiap TTD bagi WUS dan ibu hamil sekurangnya mengandung: • Zat besi setara dengan 60 mg besi elemental (dalam bentuk sediaan, Ferro Fumarat dan • Asam Folat 0,400 mg c. Spesifikasi Produk • Warna : Merah tua • Bentuk : Bulat atau lonjong • Tablet salut gula d. Kemasan Kemasan: sachet, blister, strip, botol dengan dimensi yang proporsional dengan isi tablet. Kemasan harus dapat menjamin stabilitas dan kualitas TTD bagi WUS dan ibu hamil e. Registrasi dan Pelabelan Registrasi dan pelabelan TTD bagi WUS dan ibu hamil dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan yang mengatur mengenai registrasi obat. 3. Spesifikasi Teknis Vitamin A sesuai Permenkes Nomor 21 Tahun 2015 tentang Standar Kapsul Vitamin A Bagi Bayi, Anak Balita, dan Ibu Nifas a. Deskripsi kapsul vitamin A Kapsul vitamin A merupakan kapsul lunak dengan ujung (nipple) yang dapat digunting, tidak transparan (opaque), dan mudah untuk dikonsumsi, termasuk masuk ke dalam mulut balita b. Spesifikasi Produk • Kapsul vitamin A 200.000 IU untuk anak balita usia 12 (dua belas) sampai dengan 59 (lima puluh sembilan) bulan dan ibu nifas: – Kapsul lunak berwarna merah; dan – Tiap kapsul gelatin lunak mengandung Retinol (palmitate/acetate) 200.000 IU • Kapsul vitamin A 100.000 IU bagi bayi usia 6 (enam) sampai dengan 11 (sebelas) bulan: – Kapsul lunak berwarna biru; dan – Tiap kapsul gelatin lunak mengandung Retinol (palmitate/acetate) 100.000 IU c. Kemasan Botol tidak transparan (opaque) dengan dimensi proporsional terhadap isi kapsul. Kemasan harus dapat menjamin stabilitas dan kualitas kapsul vitamin A. d. Registrasi dan Pelabelan Registrasi dan pelabelan kapsul vitamin A bagi bayi, anak balita, dan ibu nifas dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan yang mengatur mengenai registrasi obat. 7. Spesifikasi Ready-to-Use Therapeutic Food (RUTF) sesuai dengan KAK, Masa kedaluarsa RUTF adalah 18 bulan sejak sampai di alokasi distribusi yang telah ditentukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2591436);
