INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66150313', 66150313, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Vaksin Hexavalent Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 71223057000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Vaksin Hexavalent Tahun 2026 sebanyak 74.972 vial dengan estimasi harga satuan Rp950.000', 'Spesifikasi Vaksin Hexavalent sebagai berikut : 1. Nama DPT-HB-Hib-IPV vaccine. 2. Komposisi Vaksin Setiap satu dosis (0,5 ml) minimal mengandung zat aktif: - Toksoid difteri murni: ≥ 30 IU, - Toksoid tetanus murni: ≥ 40 IU, - Bakteri pertusis: ≥ 4 IU, - HBsAg: 15 mcg, - Konjugat Hib: 10 mcg, - Virus poliomyelitis type 1: Mahoney strain 40 UD (unit antigen D), - Virus poliomyelitis type 2: MEF-1 strain 8 UD, - Virus poliomyelitis type 3: Saukett 32 UD, - Al3+ sebagai alumunium fosfat: 1.25 mg. 3. Indikasi Vaksin Mencegah penyakit Difteri, Pertusis, Tetanus, Hepatitis B, Haemophilus influenzae tipe b dan Polio tipe 1, tipe 2, dan tipe 3. 4. Kemasan : Dikemas dalam single dose atau multi dose,  Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas dan/atau Vaccine Vial Monitor (VVM),  Dilengkapi dengan nomor batch, masa kedaluwarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia. 5. Masa Kadaluarsa Masa kadaluarsa vaksin saat diterima di pusat/ provinsi minimal 14 bulan. 6. Izin Vaksin Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM). 7. Persyaratan rilis dan pendistribusian vaksin :  Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum didistribusikan,  Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2592839);
