INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66194115', 66194115, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Laptop Penunjang Kegiatan Laboratorium dan Perangkat Keuangan TA 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 850000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '23 unit laptop', 'Pengadaan laptop untuk menunjang kegiatan laboratorium (pengolahan data, komputasi, pengolahan/analisis data, pelaporan, serta operasional perangkat lunak pendukung) dan sebagai perangkat kerja fungsi keuangan (pengelolaan administrasi, pelaporan, dan penggunaan aplikasi keuangan/perbendaharaan). Termasuk perangkat utama, sistem operasi sesuai spesifikasi, serta layanan garansi/purna jual sesuai ketentuan.', 'Pengadaan 23 (dua puluh tiga) unit laptop untuk menunjang kegiatan laboratorium (olah data/komputasi, pengoperasian perangkat lunak analisis/olah data, pelaporan) serta perangkat kerja fungsi keuangan (administrasi, pelaporan, aplikasi perkantoran/keuangan). Spesifikasi berbasis kinerja dan kompatibilitas serta berlaku “atau setara/ekivalen”, dibuktikan melalui datasheet resmi pabrikan dan/atau tautan laman resmi. Ketentuan kompatibilitas (berlaku untuk seluruh unit): (1) mendukung Windows 11 Pro 64-bit atau setara, TPM 2.0, Secure Boot, dan enkripsi perangkat (BitLocker atau setara); (2) tersedia dukungan driver dan firmware resmi pabrikan serta pembaruan keamanan yang dapat diverifikasi; (3) mendukung integrasi manajemen perangkat/endpoint/MDM organisasi (atau setara) sesuai dokumentasi resmi; (4) mendukung docking/monitor melalui USB-C Power Delivery dan DisplayPort Alt Mode, minimal tersedia ≥1 port USB-C yang mendukung pengisian daya dan output display; (5) dukungan purna jual resmi dan ketersediaan layanan/garansi sesuai ketentuan. Pembagian kebutuhan minimal (atau setara/ekivalen): A) 11 unit laptop bisnis 14” dengan CPU kelas performa tinggi mobile minimal ≥16 core dan ≥16 thread, RAM ≥32GB DDR5, SSD ≥1TB NVMe PCIe Gen4, grafis terintegrasi modern setara, OS Windows 11 Pro, dan garansi/layanan minimal 3 tahun setara onsite/premier; B) 5 unit laptop ultralight 14” touch dengan CPU kelas hemat daya modern, RAM ≥16GB, SSD ≥1TB NVMe, layar IPS touch atau setara, kamera IR + privacy shutter atau setara, fingerprint atau setara, OS Windows 11 Pro, garansi minimal 3 tahun; C) 1 unit laptop performa tinggi dengan CPU kelas workstation mobile, GPU dedicated kelas tinggi dengan VRAM minimal 8GB, RAM ≥16GB, SSD ≥1TB NVMe, layar minimal QHD+ dengan refresh ≥240Hz atau setara, OS Windows 11 atau setara; D) 2 unit laptop performa tinggi 14” OLED dengan RAM ≥32GB, SSD ≥1TB NVMe, GPU dedicated VRAM minimal 8GB, layar OLED resolusi minimal ≥3K, refresh ≥120Hz, brightness ≥500 nits atau setara, OS Windows 11, garansi minimal 2 tahun resmi atau setara; E) 3 unit laptop detachable 12.3” dengan layar FHD+ touch (±1920×1280) minimal ≥400 nits dan 100% sRGB atau setara, RAM ≥32GB LPDDR5x, SSD ≥1TB NVMe PCIe Gen4, Wi-Fi minimal ≥6E, kamera IR atau setara, port minimal 2× USB-C (salah satunya setara USB4/Thunderbolt), termasuk stylus/pen digital dan carrying case atau setara, OS Windows 11 Pro, garansi minimal 3 tahun onsite atau setara; F) 1 unit laptop konvertibel 14” 2-in-1 dengan layar WUXGA IPS touch minimal ≥500 nits dan 100% sRGB atau setara, RAM ≥32GB LPDDR5x, SSD ≥1TB NVMe, Wi-Fi minimal ≥7, port lengkap minimal USB-C setara USB4/Thunderbolt + HDMI + USB-A atau setara, termasuk pen dan carrying case atau setara, OS Windows 11 Pro, garansi minimal 3 tahun termasuk perlindungan perangkat (ADP atau setara). Ketentuan umum: barang baru dan resmi (bukan refurbish/bekas), termasuk adaptor/charger original dan kelengkapan standar pabrikan; serah terima disertai BAST, daftar serial number, bukti garansi/aktivasi layanan, dan dukungan purna jual sesuai garansi.', 170000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2594102);
