INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66194476', 66194476, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Acoustic Release System for Shallow Water (Deck Topside Release + Release Transponder) atau setara', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 900000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 (satu) set', 'Pengadaan 1 (satu) set sistem acoustic release perairan dangkal/continental shelf untuk operasi pelepasan (release) dan pemulihan (recovery) perangkat bawah air, terdiri dari unit kendali permukaan (deck topside + dunker) dan 1 (satu) unit release transponder. Sistem harus mendukung konfigurasi, komunikasi akustik, pelaksanaan release, serta pencatatan/logging operasi.', '1) Ruang lingkup paket: - 1 (satu) set sistem acoustic release untuk operasi perairan dangkal/continental shelf, terdiri dari: a) Deck Topside Release/Control Unit (unit kendali permukaan) b) Dunker/portable transducer untuk komunikasi akustik (shallow water kit) c) 1 (satu) unit Release Transponder / Acoustic Release 2) Deck Topside Release/Control Unit (minimum): - Portable/rugged untuk lingkungan maritim. - Proteksi lingkungan minimum setara IP67 (saat tertutup/transport). - Layar sentuh ±7 inci, tipe resistif (atau setara) untuk penggunaan luar ruangan. - Memiliki tombol fisik untuk fungsi operasi kritikal (atau setara). - Mendukung command & control komunikasi akustik, eksekusi release, dan pemantauan status. - Memiliki fungsi logging data operasi dan kemampuan ekspor data (atau setara). 3) Dunker/portable transducer (minimum): - Kompatibel dengan topside untuk komunikasi akustik operasi shallow water. - Termasuk kabel/aksesoris standar untuk operasi lapangan (atau setara). 4) Release Transponder / Acoustic Release (minimum): - Depth rating minimum 1.000 m. - SWL minimum 150 kg (rasio 4:1) atau setara. - Mekanisme release tipe screw-off atau setara. - Baterai alkaline (atau setara) dengan masa deployment minimum 13 bulan (bergantung duty cycle). - Inclinometer akurasi ±5° atau setara. - Mendukung konfigurasi & diagnostik (mis. NFC atau setara). 5) Kelengkapan & garansi: - Termasuk kelengkapan standar agar sistem dapat dioperasikan sebagai 1 set. - Garansi minimum 1 (satu) tahun. - Manual/dokumen operasi dan panduan konfigurasi (hardcopy/softcopy) atau setara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2594183);
