INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66236008', 66236008, 'analyze_legacy', 'Kab. Pangandaran', 'kabkota', 'DINAS LINGKUNGAN HIDUP DAN KEBERSIHAN', 'Belanja Jasa Konsultansi Perencanaan Pemeliharaan Taman', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Pangandaran (Kab.)', 19770000, 'March 2026', 'APBD', 1, 1, '1', 'Dalam rangka mewujudkan Visi Kabupaten Pangandaran yaitu “Mewujudkan Kabupaten Pangandaran sebagai Daerah Tujuan Wisata Dunia”. Dalam rangka mencapai visi yang telah ditetapkan, maka visi tersebut diimplementasikan dalam beberapa Misi Pembangunan, salah satunya upaya Program Pembangunan Pertamanan di Kabupaten Pangandaran yaitu dengan memelihara taman-taman di pusat pariwisata sehingga meningkatkan kualitas pelayanan dan kenyamanan para pengunjung dan juga dalam rangka pencapaian pembangunan yang berkelanjutan. Adapun Pemerintah Kabupaten Pangandaran Dalam hal ini melakukan penyusunan konsep perencanaan Pemeliharaan Taman di kawasan Ruang Terbuka Hijau (RTH) Kabupaten Pangandaran. Dalam mewujudkan Misi tersebut, Pemerintah Kabupaten Pangandaran Tahun Anggaran 2026 melalui Dinas Lingkungan Hidup Kabupaten Pangandaran mengalokasikan anggaran untuk kegiatan Ruang Terbuka Hijau (RTH), Pekerjaan Belanja Jasa Konsultansi Perencanaan Pemeliharaan Taman sebesar Rp. 19.770.000,- (Sembilan Belas Juta Tujuh Ratus Tujuh Puluh Ribu Rupiah).', 'Belanja Jasa Konsultansi Perencanaan Spesifikasi:250,000,000 s/d 300,000,000', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2594913);
