INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66194545', 66194545, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan 5-Axis CNC Tool Grinder (QD580 atau setara)', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 4600000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 (satu) paket', 'Pengadaan 5-Axis CNC Tool Grinder (atau setara) meliputi penyediaan 1 unit mesin beserta kelengkapan standar dan aksesori pendukung; pengiriman sampai lokasi pengguna (loco/lokasi serah-terima sesuai kontrak); instalasi dan commissioning; pelatihan operator dan maintenance (onsite/offline); penyerahan dokumen teknis (manual, datasheet, sertifikat/COO bila ada, daftar sparepart/consumable); serta layanan purna jual dan garansi sesuai ketentuan kontrak.', 'Spesifikasi teknis minimum 5-Axis CNC Tool Grinder (atau setara): Sistem CNC 5-axis dan software tool grinding. Kapasitas benda kerja minimum: diameter 3–32 mm (bar) dan/atau setara; panjang kerja minimum ±370 mm; beban benda kerja minimum 20 kg. Spindle grinding minimum 24 kW; kompatibel grinding wheel CBN/Diamond Ø50–Ø200 mm; rentang putaran spindle minimum 1.000–6.000 rpm (atau setara). Akurasi/runout radial spindle workpiece dan grinding head maksimum ≤0,005 mm; resolusi sumbu linear minimum 0,0001 mm; resolusi sumbu rotasi minimum 0,0001° (atau setara). Kelengkapan minimum termasuk: probing system untuk setting/measurement (setara Renishaw RP3), electrical cabinet dengan pendingin (AC), sistem pemadam otomatis di cabinet/area yang relevan, tool holder & collet setara W25, serta kelengkapan standar operasi. Utilitas minimum: AC 380V 50Hz; daya total sekitar 32 kW (atau setara). Termasuk layanan: pengiriman, instalasi/commissioning, pelatihan onsite, dan garansi minimal 12 bulan (dihitung sejak serah-terima/commissioning sesuai kontrak).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2595740);
