INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66198372', 66198372, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '693673 KANTOR PUSAT DIREKTORAT JENDERAL PLANOLOGI KEHUTANAN', 'Pekerjaan Pengadaan Operator Pengelola Website Sinpasdok KPH dan SIG', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 67500000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 Orang', 'Ruang lingkup pekerjaan pengadaan jasa konsultansi operator pengelola website Sinpasdok KPH dan SIG meliputi: 1. Melakukan tugas operator basis data dan SIG: a) Rekonstruksi database dan penyusunan tabel rekapitulasi data, guna memperbaiki beberapa kendala dalam penyajian data, antara lain: - Tabel rekapitulasi masih terdapat singkatan-singkatan; - Masih terdapat data KPH yang tidak sempurna ketika dilakukan pivot; - Tabel rekapitulasi folu, belum ada kolom nama KPH; - Tabel rekapitulasi potensi belum sesuai dengan data yang diisi oleh KPH; - Tabel rekapitulasi KPH mana yang aktif dalam pengisian data informasi, maupun konten KPH. b) Pengembangan menu blog untuk dokumentasi sesuai kebutuhan admin 2. Pengembangan untuk integrasi website sinpasdok dengan Dinas Kehutanan (maksimal 15 Provinsi) dan/atau website Kementerian Kehutanan Pusat. 3. Optimalisasi story map 4. Melakukan pengelolaan dengan pengisian dan pemutakhiran data dan informasi pada Sinpasdok KPH. 5. Membantu tugas SIG Subdit dan design analisis pemodelan keruangan. 6. Melakukan pemeliharaan website agar berjalan dengan baik. 7. Membantu tugas Subdit dan/atau atas perintah pimpinan. 8. Ikut serta dalam rapat pembahasan dan kegiatan Subdit yang relevan. 9. Membuat jadwal pekerjaan yang bersifat rutin dalam pengelolaan Website Sinpasdok KPH. 10. Penyusunan laporan bulanan dan akhir.', 'Sesuai KAk', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2597568);
